using ManpowerManagement.Data;using ManpowerManagement.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;
namespace ManpowerManagement.Pages.Tickets;
public class CreateModel(AppDbContext db):PageModel{public class InputModel{public string RequesterEmployeeId{get;set;}="";public string RequesterShift{get;set;}="Day";public int WorkshopId{get;set;}public int EmployeeId{get;set;}}[BindProperty]public InputModel Input{get;set;}=new();public List<SelectListItem> Workshops{get;set;}=[];public record EmployeeInfo(int Id,string EmployeeId,string FullName,string JobGrade,string Process,string Workshop,string Shift,string Type,string StartDate,string Phone);public List<EmployeeInfo> Employees{get;set;}=[];[TempData]public string? Message{get;set;}public async Task OnGetAsync()=>await Load();public async Task<IActionResult> OnPostAsync(){if(!await db.Employees.AnyAsync(x=>x.Id==Input.EmployeeId&&x.EmploymentState==EmploymentState.Active)){ModelState.AddModelError("Input.EmployeeId","Please select an employee from the search results.");await Load();return Page();}if(!await db.Employees.AnyAsync(x=>x.EmployeeId==Input.RequesterEmployeeId)){ModelState.AddModelError("Input.RequesterEmployeeId","Requester ID not found.");await Load();return Page();}db.ResignationTickets.Add(new ResignationTicket{RequesterEmployeeId=Input.RequesterEmployeeId,RequesterShift=Input.RequesterShift,WorkshopId=Input.WorkshopId,EmployeeId=Input.EmployeeId});db.AuditLogs.Add(new AuditLog{EntityName="ResignationTicket",EntityKey=Input.EmployeeId.ToString(),Action="Submitted",Actor=Input.RequesterEmployeeId});await db.SaveChangesAsync();Message="Ticket submitted.";return RedirectToPage();}async Task Load(){Workshops=await db.Workshops.OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync();Employees=(await db.Employees.Include(x=>x.CurrentWorkshop).Where(x=>x.EmploymentState==EmploymentState.Active).OrderBy(x=>x.FullName).ToListAsync()).Select(x=>new EmployeeInfo(x.Id,x.EmployeeId,x.FullName,x.JobGrade,x.Process,x.CurrentWorkshop!=null?x.CurrentWorkshop.Name:"",x.Shift,x.EmploymentType.ToString(),x.StartDate.ToString("yyyy-MM-dd"),x.TelephoneNumber)).ToList();}}
